<?php
/** Completes the full-format job prepared by legacy_komite_transactions_test.php. */
require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target();
if((int)getenv('SPP_DB_PORT')===3306||!getenv('SPP_KOMITE_TEST_UUID'))throw new RuntimeException('Owned isolated MySQL required.');
require_once __DIR__.'/../koneksi.php';spp_test_assert_database_target($koneksi);
if($koneksi->query('SELECT @@server_uuid')->fetch_row()[0]!==getenv('SPP_KOMITE_TEST_UUID'))throw new RuntimeException('Server UUID differs.');
require_once __DIR__.'/../includes/legacy_full.php';require_once __DIR__.'/legacy_finance_support.php';
$db=$koneksi;$unit=2;$_SESSION=['admin_role'=>'super_admin','active_unit_id'=>$unit];unit_set_context($db,$unit);lful_empty($db,$unit);$actor=(int)lf_one($db,"SELECT id FROM admin WHERE role='super_admin' AND is_active=1 LIMIT 1")['id'];$_SESSION['admin_id']=$actor;
$id=legacy_queue()->query("SELECT id FROM jobs WHERE unit=2 AND name='komite-full.dat' AND category='full' ORDER BY created DESC LIMIT 1")->fetchColumn();if(!$id)throw new RuntimeException('Run the Komite enqueue transaction test first.');$job=legacy_job($id);$draft=lful_draft($id);lft_assert(lcs_komite_enabled($draft['settings'])&&($draft['settings']['mode']??'')!=='operational','Expected a new full-format job');$year=spp_master_ensure_year($db,'2026/2027');$nis='212200002';
$rates=spp_master_rates($db,(int)$year['id']);if(in_array(0.0,$rates,true))spp_master_save_rates($db,(int)$year['id'],array_map(fn($amount)=>$amount>0?$amount:530000.0,$rates));
$patch=['cutoff'=>'2026-10-19 11:00:00','year_id'=>(int)$year['tahun_ajaran_id'],'evidence'=>'Pengujian bukti peralihan Komite dalam migrasi penuh.','accounting_reason'=>'Nominal pembayaran sumber dicocokkan secara tepat.','other_policy'=>'total_details','discount_policy'=>'information','du_policy'=>'reference','notes_accepted'=>true,'components'=>['bayar.U_SPP'=>['category'=>'spp','reason'=>'SPP sesuai kolom sumber yang telah diperiksa.','automatic_mapping'=>true]],'students'=>[$nis=>['nis'=>$nis,'name'=>'Siswa Uji Komite SMP','kind'=>'alumni','komite'=>'15000','psb'=>'0','du'=>'0','discount'=>'0','reason'=>'Klasifikasi alumni untuk fixture format penuh.','obligations_attested'=>true,'obligations_evidence'=>'Kewajiban fixture telah ditinjau secara lengkap.','coverage'=>[['category'=>'komite','period'=>'2026-10','disposition'=>'settled','amount'=>'0','evidence'=>'Komite Oktober terbayar pada U_SORGA.']]]]];
$draft=lful_save($db,$actor,$unit,$id,(int)$draft['version'],$patch);$sim=lful_simulate($db,$id);lft_assert($sim['ready']&&$sim['summary']['payment_total']==='545000.00'&&$sim['summary']['new_masters']===0,'Full Komite simulation failed: '.lf_json($sim['issues']));$confirmation=lful_confirm($db,$actor,$unit,$id,(int)$draft['version'],$sim['digest']);
require_once __DIR__.'/../includes/database_backup.php';db_backup_store(true);$backup=lful_backup($db,$actor,$id,'komite-full-test-before');putenv('SPP_FULL_TEST_FAIL=before_commit');$failed=false;
try{lful_apply_transaction($db,$job,$sim,$backup);}catch(RuntimeException $e){if(!str_contains($e->getMessage(),'before_commit'))throw $e;$failed=true;}finally{putenv('SPP_FULL_TEST_FAIL');}
lft_assert($failed&&!lf_one($db,'SELECT id FROM siswa')&&!lf_one($db,'SELECT id FROM legacy_full_payments'),'Full Komite interruption leaked partial data');
lful_enqueue_apply($db,$actor,$unit,$id,(int)$draft['version'],$confirmation['token']);lful_run($db,legacy_job($id));$batch=lful_check_result($db,$id);$manifest=json_decode($batch['manifest'],true);lft_assert($manifest['mapping']['komite_mapping_version']===1&&$manifest['mapping']['components']['bayar.U_SORGA']['migration_rule']['rule']==='sorga_is_komite','Full manifest lost source rule metadata');
$item=lf_one($db,"SELECT i.* FROM legacy_full_items i JOIN legacy_full_payments p ON p.id=i.payment_id AND p.unit_id=i.unit_id WHERE p.batch_id=? AND i.source_column='U_SORGA'",[$id]);lft_assert($item['category']==='komite'&&$item['label']==='Komite'&&$item['amount']==='15000.00','Full storage lost original column/category/amount');
$fingerprint=$manifest['projection_fingerprint'];lful_run($db,legacy_job($id));$again=lful_check_result($db,$id);lft_assert(json_decode($again['manifest'],true)['projection_fingerprint']===$fingerprint&&(int)lf_one($db,'SELECT COUNT(*) n FROM legacy_full_payments')['n']===1,'Full replay changed fingerprints or duplicated receipts');
file_put_contents(getenv('SPP_QA_DIR').'/full-migration-result.json',lf_json(['job'=>$id,'projection_fingerprint'=>$fingerprint,'payment_total'=>'545000.00','rollback'=>true,'retry'=>true]));echo "PASS: full-format Komite simulation, atomic rollback, publication fingerprint, source-column/rule metadata and idempotent replay.\n";
